// A value whose bytes count up from `seed`
template <typename T>
T filled(uint8_t seed) {
    T x;
    auto bytes = tools::byte_span(x);
    for (size_t i = 0; i < bytes.size(); i++)
        bytes[i] = std::byte(seed + i);
    return x;
}

CORE_SYNC_DATA sync_data() {
    CORE_SYNC_DATA d{};
    d.current_height = 2'231'344;
    d.cumulative_difficulty = 123'456'789'012;
    d.top_id = filled<crypto::hash>(1);
    d.top_version = hf::hf23_larger_pulse;
    d.blink_blocks = {2'231'000, 2'231'100};
    d.blink_hash = {filled<crypto::hash>(2), filled<crypto::hash>(3)};
    d.history = 0x8000'0000'0000'0001;
    return d;
}

basic_node_data node_data() {
    basic_node_data n{};
    n.network_id = filled<connection_id_t>(4);
    n.my_port = 22022;
    n.peer_id = 0x0123'4567'89ab'cdef;
    return n;
}

std::vector<peerlist_entry> peerlist() {
    std::vector<peerlist_entry> pl(3);
    pl[0].adr = oxen::quic::Address{"1.2.3.4", 22022};
    pl[0].id = 1;
    pl[0].last_seen = 1'700'000'000;
    pl[0].history = 5;
    pl[1].adr = oxen::quic::Address{"2001:db8::1", 22023};
    pl[1].id = 2;
    pl[1].last_seen = 0;
    pl[2].adr = oxen::quic::Address{"203.0.113.250", 1};
    pl[2].id = 0xffff'ffff'ffff'ffff;
    pl[2].last_seen = 1'800'000'000;
    return pl;
}

std::vector<serializable_blink_metadata> blinks() {
    std::vector<serializable_blink_metadata> b(2);
    b[0].tx_hash = filled<crypto::hash>(5);
    b[0].height = 2'231'300;
    b[0].quorum = {0, 1, 1};
    b[0].position = {3, 7, 9};
    b[0].signature = {
            filled<crypto::signature>(6),
            filled<crypto::signature>(7),
            filled<crypto::signature>(8)};
    b[1].tx_hash = filled<crypto::hash>(9);
    b[1].height = 300;
    return b;
}

block_complete_entry block_entry() {
    block_complete_entry b{};
    b.block = "block blob\0with a nul"s;
    b.txs = {"tx one", "tx two", std::string(200, 'x')};
    b.checkpoint = "checkpoint blob";
    b.blinks = blinks();
    return b;
}

COMMAND_HANDSHAKE::request handshake_request() {
    return {node_data(), sync_data()};
}

COMMAND_HANDSHAKE::response handshake_response() {
    return {node_data(), sync_data(), peerlist()};
}

COMMAND_TIMED_SYNC::request timed_sync_request() {
    return {sync_data()};
}

COMMAND_TIMED_SYNC::response timed_sync_response() {
    COMMAND_TIMED_SYNC::response r{};
    r.payload_data = sync_data();
    r.local_peerlist_new = peerlist();
    return r;
}

COMMAND_PING::response ping_response() {
    return {std::string{COMMAND_PING::OK_RESPONSE}, 0x0123'4567'89ab'cdef};
}

COMMAND_REQUEST_SUPPORT_FLAGS::response support_flags_response() {
    return {1};
}

