NOTIFY_NEW_SERVICE_NODE_VOTE::request new_service_node_votes() {
    NOTIFY_NEW_SERVICE_NODE_VOTE::request r{};
    auto& checkpoint = r.votes.emplace_back();
    checkpoint.version = 0;
    checkpoint.type = service_nodes::quorum_type::checkpointing;
    checkpoint.block_height = 2'231'340;
    checkpoint.group = service_nodes::quorum_group::validator;
    checkpoint.index_in_group = 7;
    checkpoint.signature = filled<crypto::signature>(22);
    checkpoint.checkpoint.block_hash = filled<crypto::hash>(23);
    auto& state_change = r.votes.emplace_back();
    state_change.version = 0;
    state_change.type = service_nodes::quorum_type::obligations;
    state_change.block_height = 2'231'341;
    state_change.group = service_nodes::quorum_group::worker;
    state_change.index_in_group = 300;
    state_change.signature = filled<crypto::signature>(24);
    state_change.state_change.worker_index = 9;
    state_change.state_change.state = service_nodes::new_state::decommission;
    return r;
}

GET_BLOCKS_BIN::request get_blocks_request() {
    GET_BLOCKS_BIN::request r{};
    r.block_ids = {filled<crypto::hash>(25), filled<crypto::hash>(26)};
    r.start_height = 2'231'000;
    r.prune = true;
    r.no_miner_tx = true;
    return r;
}

GET_BLOCKS_BIN::response get_blocks_response() {
    GET_BLOCKS_BIN::response r{};
    r.blocks = {block_entry()};
    r.start_height = 2'231'000;
    r.current_height = 2'231'344;
    r.status = "OK";
    r.output_indices = {{{{{0, 1, 2}}, {{70000}}}}, {}};
    r.untrusted = true;
    return r;
}

